installer-gui-script.script:
function needsDriver() {
  var root = '/Library/Audio/Plug-Ins/HAL/BlackHole2ch.driver/Contents/';
  var info = system.files.plistAtPath(root + 'Info.plist');
  if (!info || info.CFBundleIdentifier != 'audio.existential.BlackHole2ch' || !system.files.fileExistsAtPath(root + 'MacOS/BlackHole')) return true;
  var version = info.CFBundleShortVersionString;
  return !version || system.compareVersions(version, '0.7.1') < 0;
}
